  const uint32_t lead = strip.Color(255,255,255);
  for (uint16_t i = 0; i < count; ++i) {
    uint16_t phys = isBorder ? borderMap(i) : i;
    if (prev >= 0) strip.setPixelColor(prev, bg);
    strip.setPixelColor(phys, lead);
    strip.show();
    prev = phys;
    delay(5);
  }
  if (prev >= 0) strip.setPixelColor(prev, bg);
  strip.show();
