// ===================== Helpers ==================
static inline uint16_t groupBase(uint8_t group) {
  if (group < 1) group = 1;
  if (group > 36) group = 36;
  return (uint16_t)(group - 1) * 12;
}

static void clearGame() {
  for (uint16_t i = 0; i < GAME_LED_COUNT; ++i) gameStrip.setPixelColor(i, 0);
  gameStrip.show();
