static void refreshRuntimePalette(bool randomize) {
  const uint32_t defaults[6] = {
    gameStrip.Color(255, 0, 0),
    gameStrip.Color(0, 255, 0),
    gameStrip.Color(0, 0, 255),
    gameStrip.Color(255, 255, 0),
