      for (uint16_t i = 0; i < GAME_LED_COUNT; ++i) gameStrip.setPixelColor(i, col);
    } else if (previewPlayerSingleColor == 4) {
      for (uint16_t i = 0; i < GAME_LED_COUNT; ++i) {
